import { Group, Mesh, Box3, Color, PointLight, PlaneGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: TGroup, Mesh: TMesh, Box3: TBox3, Color: TColor, PlaneGeometry: TPlane } = ctx.THREE;

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const COL_BG = colors.background ?? '#0b0b10';
  const COL_SURFACE = colors.surface ?? '#111117';
  const COL_PAPER = colors.paper ?? '#e8ecf2';
  const COL_ACCENT = colors.accent ?? '#ff2a38';
  const COL_HAIRLINE = '#23232b';

  const root = new TGroup();
  root.name = 'data-ticker-ribbon';

  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;
  const GAP = 0.5;
  const TICK_W = 0.02;
  const TICK_H = 0.14;

  const disposables = [];
  const track = (geo, mat) => {
    disposables.push(geo, mat);
    return { geo, mat };
  };

  // --- rail backdrop ---
  const railGeo = new TPlane(RIBBON_W, RIBBON_H);
  const railMat = new MeshStandardNodeMaterial({
    color: new TColor(COL_SURFACE),
    roughness: 0.6,
    metalness: 0.2,
  });
  track(railGeo, railMat);
  const rail = new TMesh(railGeo, railMat);
  rail.position.z = 0;
  rail.renderOrder = 0;
  root.add(rail);

  // --- hairlines top/bottom ---
  const hairlineGeo = new TPlane(RIBBON_W, 0.006);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new TColor(COL_HAIRLINE),
    roughness: 0.5,
    metalness: 0.2,
  });
  track(hairlineGeo, hairlineMat);

  const hairlineTop = new TMesh(hairlineGeo, hairlineMat);
  hairlineTop.position.set(0, RIBBON_H / 2, 0.001);
  root.add(hairlineTop);

  const hairlineBottom = new TMesh(hairlineGeo, hairlineMat);
  hairlineBottom.position.set(0, -RIBBON_H / 2, 0.001);
  root.add(hairlineBottom);

  // --- local rim/accent light for crisp top edge on mono digits ---
  const rimLight = new PointLight(new TColor(COL_ACCENT), 0.6, 3.5);
  rimLight.position.set(0, 0.6, 1.1);
  root.add(rimLight);

  // --- tick geometry/material shared ---
  const tickGeo = new TPlane(TICK_W, TICK_H);
  const tickMat = new MeshStandardNodeMaterial({
    color: new TColor(COL_ACCENT),
    emissive: new TColor(COL_ACCENT),
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.2,
  });
  track(tickGeo, tickMat);

  // --- collect ticker text items ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  function buildStrip() {
    const strip = new TGroup();
    let cursor = 0;

    for (const item of items) {
      const fontSize = item.typography?.fontSize ?? 13;
      const letterSpacingPx = (item.typography?.letterSpacing ?? 0.06) * fontSize;
      const textObj = ctx.fontAtlas.createText(item.text ?? '', {
        fontSize,
        color: COL_PAPER,
        align: 'left',
        letterSpacingPx,
      });
      textObj.position.set(cursor, -0.01, 0.02);
      strip.add(textObj);
      textObjects.push(textObj);

      const bbox = new TBox3().setFromObject(textObj);
      const width = Number.isFinite(bbox.max.x - bbox.min.x) ? bbox.max.x - bbox.min.x : 0.6;
      cursor += width;
      cursor += GAP;

      const tick = new TMesh(tickGeo, tickMat);
      tick.position.set(cursor + TICK_W / 2, 0, 0.02);
      strip.add(tick);
      cursor += TICK_W;
      cursor += GAP;
    }

    return { strip, width: cursor };
  }

  const { strip: stripA, width: stripWidth } = buildStrip();
  const { strip: stripB } = buildStrip();
  stripB.position.x = stripWidth;

  const contentGroup = new TGroup();
  contentGroup.renderOrder = 1;
  contentGroup.add(stripA, stripB);
  root.add(contentGroup);

  // --- edge fade masks ---
  const maskGeo = new TPlane(0.6, RIBBON_H);
  track(maskGeo, null);

  const leftMaskMat = new MeshBasicNodeMaterial({
    color: new TColor(COL_BG),
    transparent: true,
    depthWrite: false,
  });
  leftMaskMat.opacityNode = oneMinus(smoothstep(0.0, 1.0, uv().x));
  track(null, leftMaskMat);

  const rightMaskMat = new MeshBasicNodeMaterial({
    color: new TColor(COL_BG),
    transparent: true,
    depthWrite: false,
  });
  rightMaskMat.opacityNode = smoothstep(0.0, 1.0, uv().x);
  track(null, rightMaskMat);

  const leftMask = new TMesh(maskGeo, leftMaskMat);
  leftMask.position.set(-RIBBON_W / 2 + 0.3, 0, 0.05);
  leftMask.renderOrder = 2;
  root.add(leftMask);

  const rightMask = new TMesh(maskGeo, rightMaskMat);
  rightMask.position.set(RIBBON_W / 2 - 0.3, 0, 0.05);
  rightMask.renderOrder = 2;
  root.add(rightMask);

  // --- cinematic primitive: fly-through (required by spec) ---
  let flyThrough = null;
  const primitiveSpec = (config.cinematicPrimitives ?? []).find((p) => p.name === 'fly-through');
  if (ctx.primitives && ctx.primitives['fly-through']) {
    flyThrough = ctx.primitives['fly-through'](contentGroup, {
      depthUnits: primitiveSpec?.params?.depthUnits ?? 0,
      speed: primitiveSpec?.params?.speed ?? 0.4,
    });
  }

  // --- guaranteed constant-velocity seamless scroll (linear, instrumentation feel) ---
  const SPEED = primitiveSpec?.params?.speed ?? 0.4;
  const tickerFn = (time, deltaMs) => {
    const dt = (deltaMs ?? 16.7) / 1000;
    contentGroup.position.x -= SPEED * dt;
    if (contentGroup.position.x <= -stripWidth) {
      contentGroup.position.x += stripWidth;
    }
  };
  gsap.ticker.add(tickerFn);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    gsap.ticker.remove(tickerFn);
    if (flyThrough && typeof flyThrough.cleanup === 'function') {
      flyThrough.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    for (const t of textObjects) {
      t.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      });
    }
    root.traverse((child) => {
      if (child === rail || child === hairlineTop || child === hairlineBottom || child === leftMask || child === rightMask) return;
      if (child.isMesh && child.geometry === tickGeo) return;
    });
  };

  return root;
}
